#include "../src/TLCore.hpp"
#include <algorithm>
extern "C" {
int pl_legacy(const float* values,const int* counts,int modern,int split,float* out){try{tl::Keys v;std::array<int,88> c;std::copy(values,values+88,v.begin());std::copy(counts,counts+88,c.begin());auto ih=tl::profile(v,c);int points=0;for(auto n:c)if(n)points++;auto params=tl::fitLegacy(ih,points,modern);auto curve=tl::legacySplit(ih,params,split,modern);std::copy(params.begin(),params.end(),out);std::copy(curve.begin(),curve.end(),out+4);return 0;}catch(...){return -1;}}
int pl_analyze(const int16_t* samples,int count,int note,float* out){try{auto r=tl::analyze(std::vector<int16_t>(samples,samples+count),note);out[0]=r.ih;for(int i=0;i<12;i++){auto p=r.partials[i];float row[]={p.bin,p.offset,p.amplitude,p.snr,p.width,float(p.valid),float(p.code)};std::copy(row,row+7,out+1+i*7);}return 0;}catch(...){return -1;}}
int pl_model(const float* values,const int* counts,int bass,int middle,int treble,int start,int modern,float* out){try{tl::Keys v;std::array<int,88> c;std::copy(values,values+88,v.begin());std::copy(counts,counts+88,c.begin());auto ih=tl::profile(v,c);auto y=tl::curve(ih,bass,middle,treble,start,modern);std::copy(ih.begin(),ih.end(),out);std::copy(y.begin(),y.end(),out+88);for(int n=0;n<88;n++)out[176+n]=tl::stretch(y,ih,n,n>47?1:6,modern);return 0;}catch(...){return -1;}}
int pl_overpull(const float* offsets,const int* present,const int* parms,float* out){try{tl::Overpull s;std::copy(offsets,offsets+88,s.offsets.begin());std::copy(present,present+88,s.present.begin());s.bass=parms[0];s.wound=parms[1];s.strut1=parms[2];s.strut2=parms[3];s.step=parms[4];if(parms[5]){s.strut1=-1;s.strut2=-1;}for(int n=0;n<88;n++)out[n]=tl::overpull(s,n);return 0;}catch(...){return -1;}}
int pl_pitch(const int16_t* samples,int count,double target,float* out){try{auto p=tl::pitch(std::vector<int16_t>(samples,samples+count),target,48,false);out[0]=p.valid;out[1]=p.hz;out[2]=p.cents;return 0;}catch(...){return -1;}}
int pl_resample(const float* samples,int count,double rate,int chunk,int16_t* out){try{tl::Resampler r(rate);int total=0;for(int i=0;i<count;i+=chunk){auto data=r.feed(samples+i,std::min(chunk,count-i));std::copy(data.begin(),data.end(),out+total);total+=data.size();}return total;}catch(...){return -1;}}
}
